<?php $escape = static fn (mixed $value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); ?>
<section class="section"><header class="admin-header"><div><h1>Usuarios Administrativos</h1><p>Gestiona las cuentas con acceso al panel y responsables de tickets.</p></div><a href="user_create.php" class="btn">Nuevo usuario</a></header><?php if ($error): ?><p class="alert alert--error"><?php echo $escape($error); ?></p><?php endif; ?><?php if (!$editing): ?><div class="table-wrapper"><table class="table table--tickets"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Creado</th><th>Acciones</th></tr></thead><tbody><?php if (!$users): ?><tr><td colspan="6">No hay usuarios administrativos registrados.</td></tr><?php else: ?><?php foreach ($users as $item): ?><tr><td><strong><?php echo $escape($item->displayName); ?></strong></td><td><?php echo $escape($item->username); ?></td><td><?php echo $item->role === 'admin' ? 'Administrador' : 'Operador'; ?></td><td><?php echo $item->active ? '<span class="ticket-assignee">Activo</span>' : '<span class="ticket-muted">Inactivo</span>'; ?></td><td><?php echo $item->createdAt ? $escape(date('d/m/Y H:i', strtotime($item->createdAt))) : 'No disponible'; ?></td><td class="table__actions"><a href="user_edit.php?id=<?php echo $item->id; ?>" class="table__action">Editar usuario</a></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div><?php else: ?><div class="card panel-card"><form method="post" class="admin-form"><input type="hidden" name="_csrf_token" value="<?php echo $csrf; ?>"><div class="admin-form__row"><div class="admin-form__group"><label class="admin-form__label" for="display_name">Nombre visible</label><input id="display_name" name="display_name" class="admin-form__input" value="<?php echo $escape($user['display_name'] ?? ''); ?>"></div><div class="admin-form__group"><label class="admin-form__label" for="username">Usuario</label><input id="username" name="username" class="admin-form__input" required value="<?php echo $escape($user['username'] ?? ''); ?>"></div></div><div class="admin-form__row"><div class="admin-form__group"><label class="admin-form__label" for="role">Rol</label><select id="role" name="role" class="admin-form__input"><option value="agent">Operador</option><option value="admin" <?php echo ($user['role'] ?? '') === 'admin' ? 'selected' : ''; ?>>Administrador</option></select></div><div class="admin-form__group"><label class="admin-form__label" for="password">Contraseña</label><input id="password" type="password" name="password" class="admin-form__input" <?php echo $user ? '' : 'required'; ?>></div></div><label class="admin-form__check"><input type="checkbox" name="active" <?php echo ($user['active'] ?? 1) ? 'checked' : ''; ?>> Activo</label><button class="btn">Guardar usuario</button></form></div><?php endif; ?></section>
